  }

  refreshMarkers();
  hudFreeRoam();

  return {
    update,
    current,
    active: activeInfo,
    start,
    abort,
    retry,
    reset,
    markers,
    serialize,
    load,
    complete,
    fail,
    step(dt, player, vehicle) {
      update(dt, deps.getMode?.() === 'car' ? (vehicle ?? deps.car) : (player ?? deps.player));
    },
  };
}
